<?php require_once __DIR__.'/includes/bootstrap.php';header('Content-Type: application/json; charset=utf-8');header('Cache-Control: public, max-age=30');
if($_SERVER['REQUEST_METHOD']!=='GET'){http_response_code(405);header('Allow: GET');echo json_encode(['error'=>'Method not allowed']);exit;}
try{$products=rows('SELECT id,name,description,category,price,stock,image_url FROM products WHERE active=1 ORDER BY id');echo json_encode(['products'=>$products],JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);}catch(Throwable $e){http_response_code(503);echo json_encode(['error'=>'Service unavailable']);}
